import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long fastPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long K = sc.nextLong();

        if (K == 0) {
            System.out.println(fastPow(p, p - 1));
            return;
        } else if (K == 1) {
            System.out.println(fastPow(p, p));
            return;
        }

        boolean[] visited = new boolean[(int) p];
        int count_cycles = 0;

        for (int i = 0; i < p; i++) {
            if (visited[i]) continue;
            int size = 0;
            long tmp = i;
            while (!visited[(int) tmp]) {
                size++;
                visited[(int) tmp] = true;
                tmp = (tmp * K) % p;
            }
            if (size > 1) count_cycles++;
        }

        System.out.println(fastPow(p, count_cycles));
    }
}
